import{_ as a}from"./chunks/schedule.ZDSBYxh8.js";import{_ as t,o,c as n,a3 as i}from"./chunks/framework.CchDE9cb.js";const f=JSON.parse(`{"title":"What is CapacityLens?","description":"A self-hosted, deliberately small tool that answers one question — who's busy, who's free, and when.","frontmatter":{"title":"What is CapacityLens?","description":"A self-hosted, deliberately small tool that answers one question — who's busy, who's free, and when."},"headers":[],"relativePath":"getting-started/what-is-capacitylens.md","filePath":"getting-started/what-is-capacitylens.md","lastUpdated":null}`),s={name:"getting-started/what-is-capacitylens.md"};function r(l,e,d,h,c,p){return o(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="what-is-capacitylens" tabindex="-1">What is CapacityLens? <a class="header-anchor" href="#what-is-capacitylens" aria-label="Permalink to &quot;What is CapacityLens?&quot;">​</a></h1><p>CapacityLens is a helicopter view of your agency&#39;s capacity: who&#39;s working on what, who&#39;s free, and when. You add your people and your projects, drag out allocations on a week-by-week calendar, and the answers — <a href="/capacitylens/reference/glossary">utilisation</a>, over-capacity days, who&#39;s free next week — appear without a report to run.</p><p>It is self-hosted and open source (AGPL), and it is built for small agencies and studios running their weekly resourcing meeting, not for large enterprises running portfolio management.</p><h2 id="what-it-does" tabindex="-1">What it does <a class="header-anchor" href="#what-it-does" aria-label="Permalink to &quot;What it does&quot;">​</a></h2><p>The whole product is one screen: <a href="/capacitylens/guide/the-schedule">the schedule</a>. It shows people grouped by <a href="/capacitylens/reference/glossary">discipline</a>, with allocation bars, live utilisation percentages, and time off — holiday, sick, unpaid — all on the same canvas, zoomable from one to eight weeks. Work hangs off a simple clients → projects → activities shape, with a built-in &quot;Internal&quot; client for the non-billable stuff. Full undo/redo and filtering by <a href="/capacitylens/reference/glossary">person</a>, discipline, client, project or <a href="/capacitylens/reference/glossary">activity</a> come with it.</p><p>Everything past that core view is a switch you flip when your team actually needs it — <a href="/capacitylens/guide/people-and-placeholders">placeholders</a> for roles you haven&#39;t hired yet, external resources for studios you hand work to, <a href="/capacitylens/guide/offline-access">offline access</a> for a read-only snapshot on the train, <a href="/capacitylens/company-login/">company login</a> when you outgrow passwords. Turning a switch off never deletes data; it comes back when you flip it again.</p><p><img src="'+a+'" alt="The Schedule view with people grouped by discipline, allocation bars, utilisation percentages and a holiday block"></p><h2 id="who-it-s-for" tabindex="-1">Who it&#39;s for <a class="header-anchor" href="#who-it-s-for" aria-label="Permalink to &quot;Who it&#39;s for&quot;">​</a></h2><p>CapacityLens is for the person who runs the Monday or Friday resourcing meeting at a small agency or studio — usually an office manager, a producer, or a founder — and for the freelancers and contractors on their books, who may never sign in at all. It assumes a team small enough that one screen can hold everyone, and a planning style measured in days and weeks, not billable minutes.</p><h2 id="what-it-deliberately-doesn-t-do" tabindex="-1">What it deliberately doesn&#39;t do <a class="header-anchor" href="#what-it-deliberately-doesn-t-do" aria-label="Permalink to &quot;What it deliberately doesn&#39;t do&quot;">​</a></h2><p>CapacityLens is deliberately <strong>not</strong>:</p><ul><li>a budgeting or billing system</li><li>a timesheet</li><li>an hour-by-hour calendar</li><li>a project-management suite</li><li>a CRM</li><li>a mobile-first app</li></ul><p>Those boundaries are on purpose, not missing features. The fastest way to stay small is to refuse the wrong ones. If you need those tools, CapacityLens is built to sit happily beside them and stick to the one question it answers best: who&#39;s busy, who&#39;s free, and when.</p><h2 id="the-scaling-ladder" tabindex="-1">The scaling ladder <a class="header-anchor" href="#the-scaling-ladder" aria-label="Permalink to &quot;The scaling ladder&quot;">​</a></h2><p>You never migrate to a &quot;bigger edition&quot; of CapacityLens — you flip the next switch when you get there. The same product runs at every size on this ladder:</p><table tabindex="0"><thead><tr><th>Stage</th><th>What changes</th></tr></thead><tbody><tr><td>Just you, evaluating</td><td><a href="/capacitylens/getting-started/try-the-demo">Try the demo</a> — one command, in-memory sample data, nothing installed beyond a copy of the code from GitHub.</td></tr><tr><td>Your team, trusted network</td><td>Real persistence, no sign-in wall. Backups on by default.</td></tr><tr><td>Real sign-ins</td><td><a href="/capacitylens/getting-started/install">Install CapacityLens</a> with password sign-in: one <a href="/capacitylens/reference/glossary">Owner</a>, invite links, four nested roles enforced on the server.</td></tr><tr><td>Company-grade identity</td><td><a href="/capacitylens/company-login/">Company login</a> (single sign-on) against your identity provider, with optional required multi-factor sign-in.</td></tr><tr><td>More than one company</td><td>Each company fully isolated — <a href="/capacitylens/reference/glossary">memberships</a>, roles and data checked per company on every request.</td></tr></tbody></table><h2 id="what-s-next" tabindex="-1">What&#39;s next <a class="header-anchor" href="#what-s-next" aria-label="Permalink to &quot;What&#39;s next&quot;">​</a></h2><p><a href="/capacitylens/getting-started/try-the-demo">Try the demo</a> to see the schedule in your browser in about two minutes, with no installation.</p>',18)])])}const g=t(s,[["render",r]]);export{f as __pageData,g as default};
